const upsertPersonLink = `-- name: UpsertPersonLink :exec

insert into person_links (person_id, identity_id, confirmed_by, confidence)
values ($1, $2, $3, 1.0)
on conflict (person_id) do update set identity_id = excluded.identity_id, confirmed_by = excluded.confirmed_by, created_at = now()
`

type UpsertPersonLinkParams struct {
	PersonID    []byte `json:"person_id"`
	IdentityID  []byte `json:"identity_id"`
	ConfirmedBy []byte `json:"confirmed_by"`
}

// Links -------------------------------------------------------------------------------------
func (q *Queries) UpsertPersonLink(ctx context.Context, arg UpsertPersonLinkParams) error {
	_, err := q.db.Exec(ctx, upsertPersonLink, arg.PersonID, arg.IdentityID, arg.ConfirmedBy)
	return err
}
